-- Published commitments only; no fabricated ETL success checkpoint.
CREATE TABLE public.mrr_instrument_snapshot (
 scope text PRIMARY KEY CHECK(scope='ico-2026'),
 metadata jsonb NOT NULL CHECK((metadata->>'version'='mrr-instruments-2026-v1' AND metadata->>'stage'='commitments-to-ico' AND jsonb_typeof(metadata->'facilities')='array' AND pg_column_size(metadata)<1000000) IS TRUE)
);
ALTER TABLE public.mrr_instrument_snapshot ENABLE ROW LEVEL SECURITY;
CREATE POLICY mrr_instrument_read ON public.mrr_instrument_snapshot FOR SELECT TO anon,authenticated USING(true);
CREATE POLICY mrr_instrument_service ON public.mrr_instrument_snapshot FOR ALL TO service_role USING(true) WITH CHECK(true);
GRANT SELECT ON public.mrr_instrument_snapshot TO anon,authenticated;
GRANT ALL ON public.mrr_instrument_snapshot TO service_role;
